const webhookData = $('Webhook Trigger').item.json;
const body = webhookData.body || webhookData;
const rawQuestion = (body.question || '').trim();
let language = (body.language || '').toLowerCase().trim();
const sessionId = body.sessionId || ('demo_' + Math.random().toString(36).substring(2, 10));
const clientTimestamp = body.timestamp || new Date().toISOString();

if (!rawQuestion || rawQuestion.length === 0) {
  throw new Error('Question cannot be empty');
}

const question = rawQuestion.substring(0, 400);

if (!language || !['en', 'de', 'hu'].includes(language)) {
  const qLower = question.toLowerCase();
  if (/[áéíóöőúüű]/i.test(qLower) || qLower.includes('ablak') || qLower.includes('mennyi') || qLower.includes('szigetel')) {
    language = 'hu';
  } else if (/[äöüß]/i.test(qLower) || qLower.includes('fenster') || qLower.includes('angebot') || qLower.includes('meter')) {
    language = 'de';
  } else {
    language = 'en';
  }
}

let targetModel = 'qwen2.5:7b';
if (language === 'hu') {
  targetModel = 'hermes3:8b';
}

let rawFileContext = '';
try {
  rawFileContext = ($('Extract Context Text').item.json.contextText || '').trim();
} catch (e) {
  rawFileContext = '';
}

let businessContext = rawFileContext;
if (language === 'de') {
  const deMatch = rawFileContext.match(/=== SECTION: DE ===([\s\S]*?)(?:=== SECTION:|$)/i);
  if (deMatch && deMatch[1].trim().length > 50) businessContext = deMatch[1].trim();
} else if (language === 'hu') {
  const huMatch = rawFileContext.match(/=== SECTION: HU ===([\s\S]*?)(?:=== SECTION:|$)/i);
  if (huMatch && huMatch[1].trim().length > 50) businessContext = huMatch[1].trim();
} else {
  const enMatch = rawFileContext.match(/=== SECTION: EN ===([\s\S]*?)(?:=== SECTION:|$)/i);
  if (enMatch && enMatch[1].trim().length > 50) businessContext = enMatch[1].trim();
}

if (!businessContext || businessContext.length < 50) {
  businessContext = 'NordicSeal Window Insulation Demo: Swedish groove-routed silicone gasket = 12 EUR/m (4,500 HUF/m). 1 standard window = 4.5m. >25m gets 10% discount. Hardware adjustment = 16 EUR/sash. Low-E thermal glass = 72 EUR/m2. Free survey in Zone A (Budapest), 10-year warranty.';
}

let systemPrompt = '';
if (language === 'de') {
  systemPrompt = `Sie sind der interaktive KI-Kundenberater und Angebotsrechner für "NordicSeal Fensterisolierung" (eine Live-KMU-Chatbot-Demo von Géza Horváth). Beantworten Sie Kundenfragen und berechnen Sie Kostenschätzungen STRIKT anhand des folgenden GESCHÄFTSDOSSIERS auf Deutsch.\n\n### REGELN:\n1. Verwenden Sie AUSSCHLIESSLICH die Preise, Formeln (z. B. 4,5 m pro Standardfenster, 10 % Mengenrabatt über 25 Laufmeter) und Fakten aus dem Dossier.\n2. Zeigen Sie bei Preisanfragen die Berechnung Schritt für Schritt übersichtlich vor.\n3. Wenn nach etwas außerhalb des Dossiers gefragt wird, sagen Sie höflich, dass dies nicht in den hinterlegten Firmendokumenten steht.\n4. Antworten Sie präzise und freundlich (2-6 Sätze oder kurze Bullet-Points).\n\n### GESCHÄFTSDOSSIER & PREISLISTE:\n${businessContext}`;
} else if (language === 'hu') {
  systemPrompt = `Te a "NordicSeal Ablakszigetelés" interaktív AI ügyfélszolgálati és árkalkulátor asszisztense vagy (Horváth Géza élő KKV chatbot demója). Válaszolj az ügyfelek kérdéseire és készíts előzetes árkalkulációt SZIGORÚAN az alábbi ÜZLETI TUDÁSBÁZIS alapján, magyarul.\n\n### SZABÁLYOK:\n1. KIZÁRÓLAG a tudásbázisban szereplő egységárakat, méretszabályokat (pl. 1 normál ablak = 4,5 fm, 25 fm felett 10% mennyiségi kedvezmény) és tényeket használd.\n2. Árajánlatkérésnél mutasd be átláthatóan, lépésről lépésre a szorzást és az esetleges kedvezményt.\n3. Ha a dokumentáción kívüli dologról kérdeznek, jelezd udvariasan, hogy erről nincs adat a vállalkozás hitelesített dokumentációjában.\n4. Válaszolj tömören és barátságosan (2-6 mondat vagy rövid felsorolás).\n\n### ÜZLETI TUDÁSBÁZIS ÉS ÁRLISTA:\n${businessContext}`;
} else {
  systemPrompt = `You are the interactive AI Customer & Quote Calculator Assistant for "NordicSeal Window Insulation & Renovation" (a live SMB chatbot showcase built by Géza Horváth). Answer customer questions and calculate instant price estimates STRICTLY using the GROUNDED BUSINESS DOSSIER below.\n\n### STRICT GROUNDING & QUOTE RULES:\n1. Use ONLY the unit rates, window perimeter defaults (e.g., 4.5m per standard single window, 9.0m per double box window, 10% volume discount when total exceeds 25 linear meters), and operational facts in the dossier.\n2. Whenever asked for an estimate or quote, show clean step-by-step math (meters, subtotal, any 10% discount if >25m, and final estimated total in EUR or HUF).\n3. If asked about a service not in the dossier, state politely that it is not listed in NordicSeal's verified business documentation.\n4. Keep responses crisp, structured, and helpful (2-6 sentences or bullet points).\n\n### GROUNDED BUSINESS DOSSIER & PRICE LIST:\n${businessContext}`;
}

return {
  json: {
    question: question,
    language: language,
    targetModel: targetModel,
    sessionId: sessionId,
    clientTimestamp: clientTimestamp,
    systemPrompt: systemPrompt,
    startTime: Date.now()
  }
};

const prev = $('Sanitize & Build Quote Prompt').item.json;
const ollamaResponse = $input.item.json;
const answer = (ollamaResponse.response || '').trim();
const durationMs = Date.now() - prev.startTime;

return {
  json: {
    status: 'success',
    answer: answer,
    sessionId: prev.sessionId,
    language: prev.language,
    model: prev.targetModel,
    durationMs: durationMs
  }
};
